import React, { useState } from "react";

export default function LaptopsList() {
  const [laptops, setLaptops] = useState([
    {
      id: 1,
      serialNumber: "SN12345",
      studentName: "John Doe",
      description: "Screen flickers occasionally",
      urgency: "High",
      status: "In Maintenance",
    },
    {
      id: 2,
      serialNumber: "SN67890",
      studentName: "Jane Smith",
      description: "Battery drains quickly",
      urgency: "Medium",
      status: "In Maintenance",
    },
  ]);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedLaptop, setSelectedLaptop] = useState(null);

  const updateStatus = (id, newStatus) => {
    const updatedLaptops = laptops.map((laptop) =>
      laptop.id === id ? { ...laptop, status: newStatus } : laptop
    );
    setLaptops(updatedLaptops);
  };

  const handleMarkAsRepaired = (laptop) => {
    setSelectedLaptop(laptop);
    setIsModalOpen(true);
  };

  const handleConfirmRepair = () => {
    if (selectedLaptop) {
      updateStatus(selectedLaptop.id, "Repaired");
      setIsModalOpen(false);
      setSelectedLaptop(null);
    }
  };

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setSelectedLaptop(null);
  };

  return (
    <div className="p-8 space-y-8 bg-gray-50 min-h-screen">
      <h2 className="text-2xl font-semibold text-gray-900">
        Laptops Under Maintenance
      </h2>
      <p className="text-sm text-gray-600">
        Below is the list of laptops currently marked for maintenance.
      </p>
      <div className="overflow-x-auto">
        <table className="min-w-full bg-white rounded-lg shadow-sm">
          <thead className="bg-indigo-600 text-white">
            <tr>
              <th className="px-6 py-3 text-left text-sm font-medium uppercase">
                Serial Number
              </th>
              <th className="px-6 py-3 text-left text-sm font-medium uppercase">
                Student Name
              </th>
              <th className="px-6 py-3 text-left text-sm font-medium uppercase">
                Description
              </th>
              <th className="px-6 py-3 text-left text-sm font-medium uppercase">
                Urgency
              </th>
              <th className="px-6 py-3 text-left text-sm font-medium uppercase">
                Status
              </th>
              <th className="px-6 py-3 text-left text-sm font-medium uppercase">
                Actions
              </th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-200">
            {laptops.map((laptop) => (
              <tr key={laptop.id} className="hover:bg-gray-100">
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                  {laptop.serialNumber}
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                  {laptop.studentName}
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                  {laptop.description}
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                  <span
                    className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-medium ${
                      laptop.urgency === "High"
                        ? "bg-red-100 text-red-800"
                        : laptop.urgency === "Medium"
                        ? "bg-yellow-100 text-yellow-800"
                        : "bg-green-100 text-green-800"
                    }`}
                  >
                    {laptop.urgency}
                  </span>
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                  {laptop.status}
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm">
                  <button
                    onClick={() => handleMarkAsRepaired(laptop)}
                    className="rounded-md bg-indigo-600 px-3 py-1 text-white text-sm font-semibold hover:bg-indigo-500"
                  >
                    Mark as Repaired
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Modal for confirming repair */}
      {isModalOpen && (
        <div className="fixed inset-0 z-10 flex items-center justify-center bg-black bg-opacity-50">
          <div className="bg-white p-6 rounded-lg shadow-lg w-1/3">
            <h3 className="text-lg font-semibold text-gray-900 mb-4">
              Confirm Laptop Repair
            </h3>
            <p className="text-sm text-gray-600 mb-4">
              Are you sure you want to mark this laptop as repaired?
            </p>
            <div className="flex justify-between">
              <button
                onClick={handleConfirmRepair}
                className="rounded-md bg-green-600 px-4 py-2 text-white font-semibold hover:bg-green-500"
              >
                Yes, Mark as Repaired
              </button>
              <button
                onClick={handleCloseModal}
                className="rounded-md bg-gray-600 px-4 py-2 text-white font-semibold hover:bg-gray-500"
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
